import{_ as t,o,c as s,a2 as n}from"./chunks/framework.CFuv5BrO.js";const h=JSON.parse('{"title":"Current Delivery Status","description":"Code, automated tests, builds, and deliberately unfinished work as of 2026-11-23.","frontmatter":{"title":"Current Delivery Status","description":"Code, automated tests, builds, and deliberately unfinished work as of 2026-11-23.","outline":[2,3]},"headers":[],"relativePath":"en/delivery/status.md","filePath":"en/delivery/status.md","lastUpdated":1795427057000}'),r={name:"en/delivery/status.md"};function a(i,e,d,l,c,u){return o(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="current-delivery-status" tabindex="-1">Current Delivery Status <a class="header-anchor" href="#current-delivery-status" aria-label="Permalink to &quot;Current Delivery Status&quot;">​</a></h1><p>Checked on 2026-11-23 against <code>main</code>, target version <code>0.3.4</code>. This page records only what current code and local runs can prove; a page existing is not a closed loop, and an old plan is not current status.</p><blockquote><p>Phase 2–6 pages are historical plans; parts of them are superseded by the current scope. Use this page for current facts. The Chinese page is canonical and includes the full 2026-11 acceptance report.</p></blockquote><h2 id="what-changed-in-this-version" tabindex="-1">What changed in this version <a class="header-anchor" href="#what-changed-in-this-version" aria-label="Permalink to &quot;What changed in this version&quot;">​</a></h2><ul><li><strong>Runtime stability:</strong> Tool side effects split into business settlement and physical cleanup. <code>settled</code> no longer means &quot;cleaned&quot;; terminal runs really terminate registered shell processes and write <code>confirmed / failed</code> back to <code>run_operations</code>. The recovery gate walks the parent run chain and refuses to replay unknown side effects.</li><li><strong>Single source of truth:</strong> The server no longer writes JSONL journals. Messages, tool settlements, checkpoints, and run boundaries go to SQLite <code>events</code> (schema v40); checkpoint files are materialized views rebuilt from <code>event_seq</code>.</li><li><strong>Host lifecycle:</strong> <code>HostKernel</code> owns the single data-directory lease and advances through <code>lease → store → operations → runs → tasks → background → ready</code>. <code>/api/ready</code> returns 503 and write routes return <code>HOST_NOT_READY</code> until recovery completes.</li><li><strong>Windows native sandbox:</strong> <code>hearth-native.exe</code> starts children with an AppContainer package SID, workspace/temp ACLs, a kill-on-close Job Object, and a parent watchdog. Network is <code>deny | open</code>; declared host allowlists or a missing helper fail closed.</li><li><strong>PTY and background processes:</strong> <code>shell</code> supports <code>pty: true</code> with <code>cols</code> / <code>rows</code>; <code>shell_input</code> and <code>shell_resize</code> operate the ConPTY session. Every session is recorded in <code>background_processes</code>; restart kills matching process trees and marks reused PIDs <code>lost</code>.</li><li><strong>Evidence and pruning:</strong> Every terminal run writes <code>run-evidence.json</code>; the long-run matrix grew from 12 to 18 crash points; <code>npm run storage:prune</code> previews and reclaims old runs and unreferenced tool output.</li><li><strong>UI contraction:</strong> Task list, task detail, and the &quot;Needs you&quot; inbox pages are gone. Runs render inline in chat; primary navigation is Chat, Library, and Context, with Mail / Schedules / Connections under More.</li></ul><h2 id="automated-verification" tabindex="-1">Automated verification <a class="header-anchor" href="#automated-verification" aria-label="Permalink to &quot;Automated verification&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Command</th><th>Result</th></tr></thead><tbody><tr><td>Version consistency</td><td><code>npm run version:check</code></td><td>0.3.4 across 7 workspaces, Cargo, Tauri, and the lockfile</td></tr><tr><td>Typecheck</td><td><code>npm run typecheck</code></td><td>0 errors</td></tr><tr><td>Unit/integration</td><td><code>npm test</code></td><td>140 files, 946 cases (931 passed, 15 skipped, 0 failed)</td></tr><tr><td>Long-run matrix</td><td><code>npm run test:longrun</code></td><td>18/18 passed</td></tr><tr><td>Web build</td><td><code>npm run build</code></td><td>Passed (JS 643.06 kB / CSS 158.97 kB)</td></tr><tr><td>Docs build</td><td><code>npm run docs:build</code></td><td>Passed</td></tr><tr><td>Offline first run</td><td><code>npm run first:run -- --fake</code></td><td>Passed (script and task chain only; not a real model)</td></tr><tr><td>0.3.4 installer</td><td><code>npm run release:build</code></td><td>NSIS 30.5 MiB, portable zip 47.2 MiB; published as a GitHub Pre-release</td></tr><tr><td>Windows sandbox</td><td><code>npm run test:sandbox</code></td><td>12 real tests: escape write, read-only, junction escape, secret filtering, network deny, PTY, and Job close</td></tr></tbody></table><blockquote><p>Real process tests (worktrees, subagents, sandbox) are slow on Windows; Vitest uses a 20-second test timeout and 30-second hook timeout. Results above were re-run on <code>main</code> on 2026-11-23. The 0.2.0 and 0.3.3 snapshots remain historical records in the Chinese acceptance report.</p></blockquote><h2 id="still-deliberately-open" tabindex="-1">Still deliberately open <a class="header-anchor" href="#still-deliberately-open" aria-label="Permalink to &quot;Still deliberately open&quot;">​</a></h2><ul><li><strong>Updater signing is not shipped:</strong> no private key, public key, or update endpoint; 0.3.4 has no updater artifacts.</li><li><strong>No Windows Authenticode:</strong> the installer may trigger SmartScreen.</li><li><strong>Clean-machine install/uninstall is unverified:</strong> the installer was freshly installed and launched on the development machine, but not on a clean Windows user environment, upgrade path, or enterprise policy.</li><li><strong>Real-model first run is unverified:</strong> it still depends on local model configuration and provider permissions; without a working key only <code>first:run --fake</code> is available.</li><li><strong>No everyday Chrome extension bridge:</strong> the product uses a dedicated Chrome profile; sites must be logged in there. Chrome 136+ blocks remote debugging on the default profile.</li><li><strong>Real accounts are unverified:</strong> Feishu tenant, SMTP/IMAP accounts, and desktop devices have code and local tests only.</li><li><strong>No weeks-long crash-recovery drill:</strong> 18 crash points are covered by automation, not by real power loss, blue screens, or forced kills over time.</li><li><strong>Cleanup coverage is partial:</strong> registered shell processes are really terminated; resources without a cleanup handler (subagents, worktrees, browser sessions) are recorded as <code>failed</code> with a reason.</li></ul><h2 id="moved-out-of-scope" tabindex="-1">Moved out of scope <a class="header-anchor" href="#moved-out-of-scope" aria-label="Permalink to &quot;Moved out of scope&quot;">​</a></h2><ul><li>Task list, task detail, and the &quot;Needs you&quot; inbox;</li><li>task templates;</li><li>proactive service, attention budgets, standing intents, and suggestion clusters;</li><li>goal contracts and automatic completion judgment;</li><li>method learning bound to tasks;</li><li>multi-device sync, remote nodes, and an executor plugin marketplace.</li></ul><p>Reintroducing these requires separate design and acceptance; old documents do not make them available.</p>',13)])])}const g=t(r,[["render",a]]);export{h as __pageData,g as default};
